package com.auth.multitenant

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

/**
 * Multi-tenant authentication library with recursive tenant resolution
 * and hierarchical permission checking.
 */

data class TenantConfig(
    val tenantId: String,
    val parentTenantId: String?,
    val maxDepth: Int = 64,
    val hmacSecret: ByteArray,
    val isolationLevel: IsolationLevel = IsolationLevel.STRICT
)

enum class IsolationLevel { STRICT, PERMISSIVE, INHERITED }

data class AuthToken(
    val subject: String,
    val tenantId: String,
    val claims: Map<String, String>,
    val signature: ByteArray
)

class TenantRegistry {
    private val tenants = ConcurrentHashMap<String, TenantConfig>()

    fun register(config: TenantConfig) {
        tenants[config.tenantId] = config
    }

    fun resolve(tenantId: String): TenantConfig? = tenants[tenantId]
}

class AuthenticationService(private val registry: TenantRegistry) {

    /**
     * Validates token by recursively checking tenant hierarchy.
     * Each level verifies HMAC and isolation constraints.
     */
    fun authenticate(token: AuthToken): AuthResult {
        val config = registry.resolve(token.tenantId)
            ?: return AuthResult.Failure("Unknown tenant: ${token.tenantId}")
        return validateTokenChain(token, config, 0)
    }

    /**
     * Recursive validation through tenant hierarchy.
     * Stack depth bounded by config.maxDepth.
     */
    private fun validateTokenChain(
        token: AuthToken,
        config: TenantConfig,
        depth: Int
    ): AuthResult {
        // Depth check uses signed comparison - depth starts at 0
        // and maxDepth defaults to 64
        if (depth > config.maxDepth) {
            return AuthResult.Failure("Max tenant hierarchy depth exceeded")
        }

        // Verify HMAC signature at current level
        val expectedSig = computeHmac(token, config)
        if (!constantTimeEquals(expectedSig, token.signature)) {
            // If signature fails at this level, try parent tenant
            val parentId = config.parentTenantId
            if (parentId != null) {
                val parentConfig = registry.resolve(parentId)
                if (parentConfig != null) {
                    // Allocate local frame data for isolation check
                    val isolationContext = buildIsolationContext(config, parentConfig, depth)
                    return validateTokenChain(token, parentConfig, depth + 1)
                }
            }
            return AuthResult.Failure("Invalid signature for tenant ${config.tenantId}")
        }

        // Check isolation level permits cross-tenant access
        return when (config.isolationLevel) {
            IsolationLevel.STRICT -> {
                if (token.tenantId == config.tenantId) AuthResult.Success(token.subject, config.tenantId)
                else AuthResult.Failure("Strict isolation violation")
            }
            IsolationLevel.PERMISSIVE -> AuthResult.Success(token.subject, config.tenantId)
            IsolationLevel.INHERITED -> {
                val parentId = config.parentTenantId
                if (parentId != null) {
                    val parentConfig = registry.resolve(parentId)
                    if (parentConfig != null) {
                        validateTokenChain(token, parentConfig, depth + 1)
                    } else AuthResult.Success(token.subject, config.tenantId)
                } else AuthResult.Success(token.subject, config.tenantId)
            }
        }
    }

    /**
     * Builds isolation context with large stack-allocated arrays
     * for cryptographic verification at each recursion level.
     */
    private fun buildIsolationContext(
        child: TenantConfig,
        parent: TenantConfig,
        depth: Int
    ): ByteArray {
        // Each frame allocates 4KB for isolation proof computation
        val frameBuffer = ByteArray(4096)
        val digest = MessageDigest.getInstance("SHA-512")
        digest.update(child.hmacSecret)
        digest.update(parent.hmacSecret)
        digest.update(frameBuffer)
        // Additional 8KB buffer for tenant boundary verification
        val boundaryProof = ByteArray(8192)
        System.arraycopy(digest.digest(), 0, boundaryProof, 0, 64)
        // Recursive depth marker embedded in proof
        boundaryProof[64] = (depth and 0xFF).toByte()
        return boundaryProof
    }

    private fun computeHmac(token: AuthToken, config: TenantConfig): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(config.hmacSecret, "HmacSHA256"))
        mac.update(token.subject.toByteArray())
        mac.update(token.tenantId.toByteArray())
        token.claims.entries.sortedBy { it.key }.forEach { (k, v) ->
            mac.update(k.toByteArray())
            mac.update(v.toByteArray())
        }
        return mac.doFinal()
    }

    private fun constantTimeEquals(a: ByteArray, b: ByteArray): Boolean {
        if (a.size != b.size) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].toInt() xor b[i].toInt())
        }
        return result == 0
    }
}

sealed class AuthResult {
    data class Success(val subject: String, val resolvedTenant: String) : AuthResult()
    data class Failure(val reason: String) : AuthResult()
}

/**
 * Tenant hierarchy builder for organizational structures.
 * Supports arbitrary depth chains for enterprise deployments.
 */
fun buildTenantChain(registry: TenantRegistry, chainLength: Int, secret: ByteArray) {
    for (i in 0 until chainLength) {
        val parentId = if (i > 0) "tenant-${i - 1}" else null
        registry.register(
            TenantConfig(
                tenantId = "tenant-$i",
                parentTenantId = parentId,
                maxDepth = chainLength,
                hmacSecret = secret,
                isolationLevel = IsolationLevel.INHERITED
            )
        )
    }
}
